-- 0007_completed_section.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Rename the homepage "New Anime" row to "Completed Anime"
-- The row now only shows titles whose status is FINISHED. The
-- filtering happens in the app (src/lib/db.ts) so the slug is kept
-- for backwards compatibility with the admin import tools.
-- Run in the Supabase SQL editor.
-- ============================================================

update public.sections
  set title = 'Completed Anime'
  where slug = 'new-anime';

-- ------------------------------------------------------------
-- 0008_anime_visibility.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Per-anime visibility toggle
-- Adds a boolean flag the admin flips in Admin -> Anime.
--   true  -> the title is published on the public website (default)
--   false -> the title is hidden everywhere on the public site while
--            staying fully visible and editable in the admin panel.
-- Existing rows default to true, so nothing disappears when this runs.
-- Run in the Supabase SQL editor.
-- ============================================================

alter table public.anime
  add column if not exists is_active boolean not null default true;

create index if not exists anime_active_idx on public.anime (is_active);

-- ------------------------------------------------------------
-- 0009_anime_requests.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Anime Request system
--
-- Public "Request an Anime" page + admin request management.
--
--  * anime_requests          one row per unique anime/season/type
--                            (deduplicated on the external anime API id,
--                            never on the title, so spelling differences and
--                            English/Japanese/alternative titles can't create
--                            duplicates)
--  * anime_request_supports  one row per supporter ("vote"), used for the
--                            request_count and for analytics
--  * RPCs                    submit/support run server-side and bump the
--                            count atomically, so the browser can never send
--                            a request_count of its own
--
-- Run in the Supabase SQL editor (safe to re-run).
-- ============================================================

-- ---------- 1. Requests ----------
create table if not exists public.anime_requests (
  id bigint generated by default as identity primary key,
  -- external anime metadata provider + its stable id (AniList media id)
  source text not null default 'anilist',
  external_id bigint not null,
  -- snapshot of the anime metadata at request time
  anime_title text not null,
  anime_title_english text,
  anime_title_native text,
  anime_romaji text,
  anime_cover text,
  anime_format text,
  anime_status text,
  anime_episodes integer,
  anime_year integer,
  -- which season is being requested (0 = the series as a whole)
  season integer not null default 0,
  season_year integer,
  season_label text,
  request_type text not null default 'NEW_ANIME',
  request_count integer not null default 0,
  status text not null default 'REQUESTED',
  -- set by an admin when the title goes live, so the public page can offer
  -- a "Watch Now" link back into the existing catalogue
  added_anime_id bigint references public.anime(id) on delete set null,
  first_requested_at timestamptz not null default now(),
  last_requested_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint anime_requests_unique unique (source, external_id, request_type, season),
  constraint anime_requests_type_check
    check (request_type in ('NEW_ANIME','NEW_SEASON','MISSING_EPISODE','DUB','SUBTITLE','OTHER')),
  constraint anime_requests_status_check
    check (status in ('REQUESTED','UNDER_REVIEW','PLANNED','PROCESSING','ADDED','REJECTED'))
);

create index if not exists anime_requests_rank_idx
  on public.anime_requests (request_count desc, last_requested_at desc);
create index if not exists anime_requests_status_idx
  on public.anime_requests (status, request_count desc);
create index if not exists anime_requests_recent_idx
  on public.anime_requests (last_requested_at desc);
create index if not exists anime_requests_first_idx
  on public.anime_requests (first_requested_at desc);
create index if not exists anime_requests_external_idx
  on public.anime_requests (source, external_id);

drop trigger if exists anime_requests_updated_at on public.anime_requests;
create trigger anime_requests_updated_at before update on public.anime_requests
  for each row execute function public.set_updated_at();

-- ---------- 2. Supports (votes) ----------
create table if not exists public.anime_request_supports (
  id bigint generated by default as identity primary key,
  request_id bigint not null references public.anime_requests(id) on delete cascade,
  -- authenticated user id, or a random device-scoped id for anonymous
  -- visitors. No personal information is stored.
  supporter_key text not null,
  message text,
  created_at timestamptz not null default now(),
  unique (request_id, supporter_key)
);

create index if not exists anime_request_supports_request_idx
  on public.anime_request_supports (request_id);
create index if not exists anime_request_supports_created_idx
  on public.anime_request_supports (created_at desc);
create index if not exists anime_request_supports_key_idx
  on public.anime_request_supports (supporter_key);

-- ---------- 3. Row Level Security ----------
alter table public.anime_requests         enable row level security;
alter table public.anime_request_supports enable row level security;

-- The request list is public content (counts, status, metadata).
drop policy if exists "public read anime_requests" on public.anime_requests;
create policy "public read anime_requests" on public.anime_requests
  for select using (true);

-- Supports are NOT public: they carry the optional user message and the
-- supporter key. Admins read them; everyone else goes through the RPCs.
drop policy if exists "admin manage anime_requests" on public.anime_requests;
create policy "admin manage anime_requests" on public.anime_requests
  for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists "admin manage anime_request_supports" on public.anime_request_supports;
create policy "admin manage anime_request_supports" on public.anime_request_supports
  for all using (public.is_admin()) with check (public.is_admin());

-- ---------- 4. RPCs ----------
-- Counts are only ever written here, never by the browser.

create or replace function public.anime_request_key_ok(p_key text)
returns boolean as $$
  select length(trim(coalesce(p_key, ''))) between 8 and 128;
$$ language sql immutable;

-- Create a request, or support it when it already exists.
create or replace function public.submit_anime_request(
  p_source text,
  p_external_id bigint,
  p_title text,
  p_title_english text,
  p_title_native text,
  p_romaji text,
  p_cover text,
  p_format text,
  p_status text,
  p_episodes integer,
  p_year integer,
  p_season integer,
  p_season_label text,
  p_season_year integer,
  p_request_type text,
  p_supporter_key text,
  p_message text
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_key text := trim(coalesce(p_supporter_key, ''));
  v_type text := upper(coalesce(nullif(trim(p_request_type), ''), 'NEW_ANIME'));
  v_source text := lower(coalesce(nullif(trim(p_source), ''), 'anilist'));
  v_season integer := greatest(coalesce(p_season, 0), 0);
  v_row public.anime_requests;
  v_added boolean := false;
  v_total integer := 0;
  v_recent integer := 0;
begin
  if not public.anime_request_key_ok(v_key) then
    raise exception 'invalid supporter key';
  end if;
  if p_external_id is null or p_external_id <= 0 then
    raise exception 'invalid anime id';
  end if;
  if p_title is null or length(trim(p_title)) = 0 then
    raise exception 'missing title';
  end if;
  if v_type not in ('NEW_ANIME','NEW_SEASON','MISSING_EPISODE','DUB','SUBTITLE','OTHER') then
    raise exception 'invalid request type';
  end if;

  -- Light spam guard: one device/session may contribute at most 40 times a day.
  select count(*) into v_recent
    from public.anime_request_supports
   where supporter_key = v_key and created_at > now() - interval '1 day';
  if v_recent >= 40 then
    raise exception 'rate limited';
  end if;

  insert into public.anime_requests as r (
    source, external_id, anime_title, anime_title_english, anime_title_native, anime_romaji,
    anime_cover, anime_format, anime_status, anime_episodes, anime_year,
    season, season_label, season_year, request_type
  ) values (
    v_source, p_external_id, trim(p_title),
    nullif(trim(coalesce(p_title_english, '')), ''),
    nullif(trim(coalesce(p_title_native, '')), ''),
    nullif(trim(coalesce(p_romaji, '')), ''),
    nullif(trim(coalesce(p_cover, '')), ''),
    nullif(trim(coalesce(p_format, '')), ''),
    nullif(trim(coalesce(p_status, '')), ''),
    p_episodes, p_year,
    v_season, nullif(trim(coalesce(p_season_label, '')), ''), p_season_year, v_type
  )
  on conflict (source, external_id, request_type, season) do update
    set last_requested_at = now(),
        anime_cover = coalesce(r.anime_cover, excluded.anime_cover),
        anime_title_english = coalesce(r.anime_title_english, excluded.anime_title_english),
        anime_title_native = coalesce(r.anime_title_native, excluded.anime_title_native),
        anime_format = coalesce(r.anime_format, excluded.anime_format),
        anime_year = coalesce(r.anime_year, excluded.anime_year),
        anime_episodes = coalesce(r.anime_episodes, excluded.anime_episodes)
  returning * into v_row;

  insert into public.anime_request_supports (request_id, supporter_key, message)
  values (v_row.id, v_key, nullif(left(trim(coalesce(p_message, '')), 300), ''))
  on conflict (request_id, supporter_key) do nothing
  returning true into v_added;
  v_added := coalesce(v_added, false);

  if v_added then
    update public.anime_requests
       set request_count = request_count + 1
     where id = v_row.id
    returning * into v_row;
  end if;

  select count(*) into v_total
    from public.anime_request_supports where request_id = v_row.id;

  return jsonb_build_object(
    'request', to_jsonb(v_row),
    'already_supported', not v_added,
    'created', v_total = 1
  );
end;
$$;

-- Support an existing request (no duplicate row, count goes up by one).
create or replace function public.support_anime_request(
  p_request_id bigint,
  p_supporter_key text,
  p_message text
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_key text := trim(coalesce(p_supporter_key, ''));
  v_row public.anime_requests;
  v_added boolean := false;
  v_recent integer := 0;
begin
  if not public.anime_request_key_ok(v_key) then
    raise exception 'invalid supporter key';
  end if;
  if p_request_id is null or p_request_id <= 0 then
    raise exception 'invalid request id';
  end if;

  select count(*) into v_recent
    from public.anime_request_supports
   where supporter_key = v_key and created_at > now() - interval '1 day';
  if v_recent >= 40 then
    raise exception 'rate limited';
  end if;

  insert into public.anime_request_supports (request_id, supporter_key, message)
  values (p_request_id, v_key, nullif(left(trim(coalesce(p_message, '')), 300), ''))
  on conflict (request_id, supporter_key) do nothing
  returning true into v_added;
  v_added := coalesce(v_added, false);

  if v_added then
    update public.anime_requests
       set request_count = request_count + 1,
           last_requested_at = now()
     where id = p_request_id
    returning * into v_row;
  else
    select * into v_row from public.anime_requests where id = p_request_id;
  end if;

  if v_row.id is null then
    raise exception 'request not found';
  end if;

  return jsonb_build_object(
    'request', to_jsonb(v_row),
    'already_supported', not v_added,
    'created', false
  );
end;
$$;

-- Request ids this visitor has already supported (drives "✓ You supported this").
create or replace function public.anime_request_support_ids(p_supporter_key text)
returns setof bigint
language sql
security definer
set search_path = public
as $$
  select request_id
    from public.anime_request_supports
   where supporter_key = trim(coalesce(p_supporter_key, ''))
     and public.anime_request_key_ok(p_supporter_key);
$$;

grant execute on function public.anime_request_key_ok(text)            to anon, authenticated;
grant execute on function public.anime_request_support_ids(text)       to anon, authenticated;
grant execute on function public.submit_anime_request(
  text, bigint, text, text, text, text, text, text, text,
  integer, integer, integer, text, integer, text, text, text
) to anon, authenticated;
grant execute on function public.support_anime_request(bigint, text, text)
  to anon, authenticated;

-- ---------- 5. Realtime ----------
-- Lets the public request counts update without a refresh.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (
      select 1 from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'anime_requests'
    ) then
      alter publication supabase_realtime add table public.anime_requests;
    end if;
  end if;
exception when others then
  raise notice 'Realtime publication not updated: %', sqlerrm;
end $$;

-- ------------------------------------------------------------
-- 0010_abyss_accounts.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Multiple abyss.to accounts for subtitle uploads
--
-- Subtitle uploads used to log in with a single account held in
-- Edge Function secrets (ABYSS_EMAIL / ABYSS_PASSWORD). This adds
-- a pool of accounts in the database: the abyss-sub function picks
-- the least-recently-used active account and automatically falls
-- back to the next one when a login or upload fails. The old
-- secrets keep working as a final fallback, so nothing breaks
-- while no accounts have been added yet.
--
-- SECURITY
--   Passwords must be stored recoverable, because the function has
--   to replay them to POST api.abyss.to/auth/login - they cannot be
--   hashed. So this table is closed to every client:
--     * RLS is enabled with NO policies (denies everything)
--     * anon and authenticated have all grants revoked
--   Only the service role - used exclusively inside the abyss-sub
--   Edge Function - can read the rows. Admins manage accounts
--   through the SECURITY DEFINER functions below, which are the
--   only path that touches the table and never return a password.
--
-- Run in the Supabase SQL editor (safe to re-run).
-- ============================================================

create table if not exists public.abyss_accounts (
  id bigint generated by default as identity primary key,
  label text not null default '',
  username text not null,
  password text not null,
  is_active boolean not null default true,
  last_used_at timestamptz,
  last_ok_at timestamptz,
  last_error text,
  failure_count integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One row per account; same login address cannot be added twice.
create unique index if not exists abyss_accounts_username_idx
  on public.abyss_accounts (lower(username));

-- ---------- 1. Close the table to every client ----------
alter table public.abyss_accounts enable row level security;

-- Belt and braces: RLS alone would deny (no policies), but remove the
-- default grants as well so nothing can even attempt a read.
revoke all on table public.abyss_accounts from anon, authenticated;
grant all on table public.abyss_accounts to service_role;

-- Adds an account (p_id null) or updates one; a blank p_password on an
-- update keeps the stored password, so renaming never needs a re-type.
create or replace function public.abyss_account_save(
  p_id bigint,
  p_label text,
  p_username text,
  p_password text
) returns bigint as $$
declare
  v_id bigint;
begin
  if not public.is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;

  if coalesce(trim(p_username), '') = '' then
    raise exception 'An abyss username or email is required.' using errcode = '22023';
  end if;

  if p_id is null then
    if coalesce(trim(p_password), '') = '' then
      raise exception 'A password is required for a new account.' using errcode = '22023';
    end if;
    insert into public.abyss_accounts (label, username, password)
    values (coalesce(trim(p_label), ''), trim(p_username), p_password)
    returning id into v_id;
  else
    update public.abyss_accounts
       set label = coalesce(trim(p_label), ''),
           username = trim(p_username),
           password = case
                        when coalesce(trim(p_password), '') = '' then password
                        else p_password
                      end,
           updated_at = now()
     where id = p_id
     returning id into v_id;

    if v_id is null then
      raise exception 'That account no longer exists.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $$ language plpgsql security definer set search_path = public;

-- Metadata only. The password is deliberately never returned, so it
-- cannot leak into the browser console, network tab or a React state tree.
create or replace function public.abyss_accounts_list()
returns table (
  id bigint,
  label text,
  username text,
  is_active boolean,
  last_used_at timestamptz,
  last_ok_at timestamptz,
  last_error text,
  failure_count integer,
  created_at timestamptz
) as $$
  select a.id,
         a.label,
         a.username,
         a.is_active,
         a.last_used_at,
         a.last_ok_at,
         a.last_error,
         a.failure_count,
         a.created_at
    from public.abyss_accounts a
   where public.is_admin()
   order by a.id;
$$ language sql stable security definer set search_path = public;

create or replace function public.abyss_account_set_active(p_id bigint, p_active boolean)
returns void as $$
begin
  if not public.is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  update public.abyss_accounts
     set is_active = p_active, updated_at = now()
   where id = p_id;
end $$ language plpgsql security definer set search_path = public;

create or replace function public.abyss_account_delete(p_id bigint)
returns void as $$
begin
  if not public.is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  delete from public.abyss_accounts where id = p_id;
end $$ language plpgsql security definer set search_path = public;

-- ---------- 2. Result tracking, for the abyss-sub function only ----------
-- Called with the service role after each attempt. Recording last_used_at
-- on every attempt is what spreads uploads across the accounts; the failure
-- counters exist so the admin panel can show which account has gone stale.
create or replace function public.abyss_account_mark(
  p_id bigint,
  p_ok boolean,
  p_error text default null
) returns void as $$
begin
  update public.abyss_accounts
     set last_used_at = now(),
         last_ok_at = case when p_ok then now() else last_ok_at end,
         last_error = case when p_ok then null else left(coalesce(p_error, ''), 500) end,
         failure_count = case when p_ok then 0 else failure_count + 1 end,
         updated_at = now()
   where id = p_id;
end $$ language plpgsql security definer set search_path = public;

-- ---------- 3. Grants ----------
-- Functions are executable by PUBLIC by default, so revoke that first.
revoke all on function public.abyss_account_save(bigint, text, text, text) from public;
revoke all on function public.abyss_accounts_list() from public;
revoke all on function public.abyss_account_set_active(bigint, boolean) from public;
revoke all on function public.abyss_account_delete(bigint) from public;
revoke all on function public.abyss_account_mark(bigint, boolean, text) from public;

-- Admins (any authenticated caller - each function re-checks is_admin()).
grant execute on function public.abyss_account_save(bigint, text, text, text) to authenticated;
grant execute on function public.abyss_accounts_list() to authenticated;
grant execute on function public.abyss_account_set_active(bigint, boolean) to authenticated;
grant execute on function public.abyss_account_delete(bigint) to authenticated;

-- Only the Edge Function's service role may record attempt results.
grant execute on function public.abyss_account_mark(bigint, boolean, text) to service_role;

-- ---------- 4. Make sure the service role can reach the table ----------
grant usage, select on sequence public.abyss_accounts_id_seq to service_role;

-- ------------------------------------------------------------
-- 0011_episode_number_decimal.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Episode numbers with a decimal part
--
-- episodes.episode_number was an integer, so half episodes
-- (12.5, 13.5) could not be stored at all. It becomes numeric,
-- following the same approach as 0003_duration_decimal.sql.
--
-- Whole numbers are unaffected: 13 still stores and sorts as 13,
-- and the existing unique (anime_id, episode_number) constraint
-- keeps working with the new type.
--
-- Note: numbering does not have to start at 1. A "Part 2" that
-- continues the previous part simply stores 13, 14, ... and the
-- site now lists only the episodes that exist.
--
-- Run in the Supabase SQL editor (safe to re-run).
--
-- The admin panel (Admin -> Anime -> Episodes) checks the column type when
-- it opens and shows this same SQL if a half episode cannot be saved yet.
-- ============================================================

alter table public.episodes
  alter column episode_number type numeric using episode_number::numeric;

-- Sorting and "latest episode" lookups go through this column.
create index if not exists episodes_number_idx
  on public.episodes (anime_id, episode_number);

-- ------------------------------------------------------------
-- 0012_comments.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Episode and movie comments
--
-- Every episode gets its own thread, and a movie that has no
-- episode row (a single video) hangs its thread off the title
-- itself, so episode_id stays null there.
--
-- SECURITY
--   Anyone may read a thread, but only a signed-in viewer may
--   write, and only rows carrying their own auth.uid() - the
--   client sends its user id, and the policy refuses anything
--   that does not match the session. Deleting is limited to the
--   author, so one viewer can never remove another's comment.
--
--   The display name and avatar are snapshotted on the row when
--   the comment is posted. Profiles carry a generated
--   "user_xxxxxxxx" name for Google sign-ins (usernames are
--   unique, real names are not), so a snapshot is what keeps the
--   thread readable; the cost is that a later name or avatar
--   change does not rewrite existing comments.
-- ============================================================

create table if not exists public.comments (
  id bigint generated by default as identity primary key,
  anime_id bigint not null references public.anime(id) on delete cascade,
  episode_id bigint references public.episodes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  author_name text not null,
  author_avatar text,
  body text not null check (char_length(btrim(body)) between 1 and 2000),
  created_at timestamptz not null default now()
);

-- Threads are read newest first, and the animelookup keeps the
-- per-title listing (a future "all comments on this anime" view)
-- from scanning the table.
create index if not exists comments_episode_idx on public.comments (episode_id, created_at desc);
create index if not exists comments_anime_idx on public.comments (anime_id, created_at desc);

alter table public.comments enable row level security;

-- the whole thread is public, signed in or not
-- (dropped first so re-running this file on a project that already has it
-- succeeds instead of failing with "policy already exists")
drop policy if exists "public read comments" on public.comments;
create policy "public read comments" on public.comments
  for select using (true);

-- signed-in viewers post as themselves, nothing else
drop policy if exists "signed in viewers post comments" on public.comments;
create policy "signed in viewers post comments" on public.comments
  for insert to authenticated with check (auth.uid() = user_id);

-- and may take back only what they wrote
drop policy if exists "viewers delete own comments" on public.comments;
create policy "viewers delete own comments" on public.comments
  for delete to authenticated using (auth.uid() = user_id);

-- ------------------------------------------------------------
-- 0013_ad_free_emails.sql
-- ------------------------------------------------------------
-- ============================================================
-- ANIMELK - Ad-free accounts
--
-- The site owner keeps a list of email addresses that should never
-- receive the Monetag tag. It is managed from the admin panel, and
-- public/ad-gate.js consults a cached answer for it before making a
-- single ad request.
--
-- SECURITY
--   The list itself is not public. A signed-in visitor may read the
--   one row that matches their own email address - that is how the
--   site knows to skip ads for the account - and only admins can
--   read or change the whole list.
--
-- Run in the Supabase SQL editor (safe to re-run).
-- ============================================================

create table if not exists public.ad_free_emails (
  email text primary key,
  note text not null default '',
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

-- Addresses are stored lower-cased, so both the lookup and the policy can
-- compare them as plain text instead of asking Postgres for a case-fold.
-- The update comes first, so an address added straight through the
-- dashboard cannot break the constraint below when this file is re-run.
update public.ad_free_emails set email = lower(email) where email <> lower(email);
alter table public.ad_free_emails
  drop constraint if exists ad_free_emails_email_check;
alter table public.ad_free_emails
  add constraint ad_free_emails_email_check
  check (email = lower(email) and position('@' in email) > 1);

alter table public.ad_free_emails enable row level security;

-- A visitor can ask about their own address and nothing else. auth.jwt() is
-- null for a signed-out browser, so the comparison never matches there.
drop policy if exists "read own ad-free row" on public.ad_free_emails;
create policy "read own ad-free row" on public.ad_free_emails
  for select using (
    lower(email) = lower(coalesce(auth.jwt() ->> 'email', ''))
  );

-- Admins manage the list.
drop policy if exists "admin read ad-free" on public.ad_free_emails;
create policy "admin read ad-free" on public.ad_free_emails
  for select using (public.is_admin());

drop policy if exists "admin insert ad-free" on public.ad_free_emails;
create policy "admin insert ad-free" on public.ad_free_emails
  for insert with check (public.is_admin());

drop policy if exists "admin update ad-free" on public.ad_free_emails;
create policy "admin update ad-free" on public.ad_free_emails
  for update using (public.is_admin()) with check (public.is_admin());

drop policy if exists "admin delete ad-free" on public.ad_free_emails;
create policy "admin delete ad-free" on public.ad_free_emails
  for delete using (public.is_admin());
